{(Cut-set Bound)}
    Any achievable rate $R$ for a primitive diamond relay channel must satisfy
    \begin{subequations}
        \begin{align}
            R\leq &I(X;Y_1,Y_2),\\
            R\leq &C_1+I(X;Y_2),\\
            R\leq &C_2+I(X;Y_1),\\
            R\leq &C_1+C_2,
        \end{align}
    \end{subequations}
    for some input distribution $p(x)$.

\cite{wu2019new}[Theorem 3.1]\label{ob:ayfergaussian}
    For a Gaussian primitive diamond relay channel, if a rate $R$ is achievable, then there exists $\theta_i\in[\arcsin(2^{-C_i}),\frac{\pi}{2}],i\in\{1,2\}$ such that
    \begin{subequations}
        \begin{align}
            R\leq& \frac{1}{2}\log(1+\frac{P}{N_1})+C_2+\log\sin\theta_2,\label{eqn:ayfergauss1}\\
            R\leq& \frac{1}{2}\log(1+\frac{P}{N_2})+\min_{\omega_1\in (\frac{\pi}{2}-\theta_1,\frac{\pi}{2}]}h_1(\omega_1;\theta_1),\label{eqn:ayfergauss2}\\
            R\leq& \frac{1}{2}\log(1+\frac{P}{N_2})+C_1+\log\sin\theta_1,\label{eqn:ayfergauss3}\\
            R\leq& \frac{1}{2}\log(1+\frac{P}{N_1})+\min_{\omega_2\in (\frac{\pi}{2}-\theta_2,\frac{\pi}{2}]}h_2(\omega_2;\theta_2),\label{eqn:ayfergauss4}\\
            R\leq & C_1+C_2+\log \sin\theta_1+\log\sin\theta_2,\label{eqn:ayfergauss5}
        \end{align}
        where 
        \begin{align}
            h_i(\omega;\theta):=\frac{1}{2}\log\bigg(\frac{[P(N_1+N_2)+N_1N_2\sin^2\omega -2P\sqrt{N_1 N_2}\cos \omega]\sin^2\theta}{N_i(P+N_{\bar i})(\sin^2\theta -\cos^2\omega)}\bigg).
        \end{align}
    \end{subequations}

\cite{wu2019new}[Theorem 3.2]\label{ob:ayferdiscrete}
For a discrete memoryless primitive diamond relay channel, if a rate $R$ is achievable, then there exists some $p(x)$ and $a_1,a_2\geq 0$ such that
\begin{subequations}
    \begin{align}
        R\leq &I(X;Y_1,Y_2),\\
        R\leq &I(X;Y_1)+C_2-a_2,\\
        R\leq &I(X;Y_1,\tilde Y_2)+H_2(\sqrt{a_2\frac{\ln 2}{2}})+\sqrt{a_2\frac{\ln 2}{2}}\log(|\mathcal{Y}_2|-1)-a_2,\\
        R\leq & I(X;Y_2)+C_1-a_1,\\
        R\leq & I(X;\tilde Y_1,Y_2)+H_2(\sqrt{a_1\frac{\ln 2}{2}})+\sqrt{a_1\frac{\ln 2}{2}}\log(|\mathcal{Y}_1|-1)-a_1,\\
        R\leq & C_1+C_2-a_1-a_2,
    \end{align}
\end{subequations}
for any random variables $\tilde Y_1$ and $\tilde Y_2$ with the same conditional distributions as $Y_1$ and $Y_2$ given $X$.

\label{ob:relayuvw}
    Any achievable rate $R$ for a primitive diamond relay channel must satisfy
    \begin{subequations}
        \begin{align}
        R\leq &I(X;Y_2)+C_1-I(U;Y_1|X),\label{eqn:obuvw1}\\
        R\leq &I(X;Y_1)+I(X;Y_2|U)-I(X;Y_1|U),\label{eqn:obuvw2}\\
        R\leq & I(X;Y_1)+C_2-I(V;Y_2|X),\label{eqn:obuvw3}\\
        R\leq & I(X;Y_2)+I(X;Y_1|V)-I(X;Y_2|V),\label{eqn:obuvw4}\\
        R\leq &C_1+C_2-I(U;Y_1|X)-I(V;Y_2|X).\label{eqn:obuvw5}
    \end{align}
    \end{subequations}
    The union is taken over distributions of the form $p(x)p(y_1|x)p(y_2|x)p(u|x,y_1)p(v|x,y_2)$, so that $U-(X,Y_1)-Y_2$ and $V-(X,Y_2)-Y_1$.
It suffices to consider auxiliaries satisfying $|U|\leq |X||Y_1|+1$, $|V|\leq |X||Y_2|+1$.

\label{rm:constraint_C}
    When evaluating Theorem~\ref{ob:relayuvw}, it suffices to consider the random variables satisfying
    \begin{align*}
        C_1&\geq I(U;Y_1|X),\\
        C_2&\geq I(V;Y_2|X).
    \end{align*}
    The argument is contained in the converse proof. For instance, we have
    \begin{align*}
        0\leq &I(X^n;J_{1,n}|Y_2^n)+H(J_{1,n}|Y_1^n,X^n,Y_2^n)\\
        \leq &n(C_1-I(U;Y_1|X)).
    \end{align*}

\label{prop:obuvwgauss}
For a Gaussian primitive diamond relay channel, any achievable rate $R$ must satisfy
    \begin{subequations}
    \begin{align}
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_2}\Bigr)+C_1
               +\tfrac{1}{2}\log\Bigl[\tfrac{K_2}{N_1}\bigl(1-\rho^2\bigr)\Bigr],
               \label{eqn:snrbound1}\\
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_1}\Bigr)
               +\tfrac{1}{2}\log\Bigl[\Bigl(1+\tfrac{K_1}{N_2}\Bigr)
                \bigl(1-\rho^2\bigr)\Bigr],\label{eqn:snrbound2}\\
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_1}\Bigr)+C_2
               +\tfrac{1}{2}\log\Bigl[\tfrac{\hat K_2}{N_2}
                \bigl(1-\hat\rho^2\bigr)\Bigr],\label{eqn:snrbound3}\\
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_2}\Bigr)
               +\tfrac{1}{2}\log\Bigl[\Bigl(1+\tfrac{\hat K_1}{N_1}\Bigr)
                \bigl(1-\hat\rho^2\bigr)\Bigr],\label{eqn:snrbound4}\\
        R\leq& C_1+C_2
               +\tfrac{1}{2}\log\Bigl[\tfrac{K_2}{N_1}\bigl(1-\rho^2\bigr)\Bigr]
               +\tfrac{1}{2}\log\Bigl[\tfrac{\hat K_2}{N_2}
                \bigl(1-\hat\rho^2\bigr)\Bigr],\label{eqn:snrbound5}
    \end{align}
    for some $0\leq K_1,\hat K_1\leq P$, $0\leq K_2\leq P+N_1$, $0\leq \hat K_2\leq P+N_2$, and $\rho,\hat \rho\in[0,1]$,
    subject to
    \begin{align}
        (P-K_1)(P+N_1-K_2)\geq& \bigl(P-\rho\sqrt{K_1 K_2}\bigr)^2,
        \label{eqn:snrbound6}\\
        (P-\hat K_1)(P+N_2-\hat K_2)\geq&
        \bigl(P-\hat \rho\sqrt{\hat K_1 \hat K_2}\bigr)^2,\label{eqn:snrbound7}\\
        C_1+\tfrac{1}{2}\log\Bigl[\tfrac{K_2}{N_1}\bigl(1-\rho^2\bigr)\Bigr]
        \geq& 0,\label{eqn:snrbound8}\\
        C_2+\tfrac{1}{2}\log\Bigl[\tfrac{\hat K_2}{N_2}
        \bigl(1-\hat\rho^2\bigr)\Bigr]\geq & 0,\label{eqn:snrbound9}
    \end{align}
\end{subequations}

By Lemma~\ref{lm:gaussianopt}, when evaluating Theorem~\ref{ob:relayuvw}, we consider the Gaussian distributions $P_X$, $P_{X,Y_1|U}$, and $P_{X,Y_2|V}$. Accordingly, let the variance of $X$ be $P_0$, and let the conditional covariances of $X,Y_1$ given $U$ and of $X,Y_2$ given $V$ be 
\begin{subequations}
\begin{align}
    K_{X,Y_1|U} =&\begin{bmatrix}
        K_1 &\rho \sqrt{K_1 K_2}\\
        \rho \sqrt{K_1 K_2} & K_2
    \end{bmatrix}\preceq \begin{bmatrix}
        P_0 & P_0\\ P_0 & P_0+N_1
    \end{bmatrix},\label{eqn:psdxyu}\\
    K_{X,Y_2|V} =&\begin{bmatrix}
        \hat K_1 &\hat \rho \sqrt{\hat K_1 \hat K_2}\\
        \hat \rho \sqrt{\hat K_1 \hat K_2} & \hat K_2
    \end{bmatrix}\preceq \begin{bmatrix}
        P_0 & P_0\\ P_0 & P_0+N_2
    \end{bmatrix},\label{eqn:psdxyv}
\end{align}
\end{subequations}
for some $0\leq K_1,\hat K_1\leq P_0$, $0\leq K_2\leq P_0+N_1$, $0\leq \hat K_2\leq P_0+N_2$, and $\rho,\hat \rho\in[-1,1]$. 

With this parameterization, it is optimal to set $P_0 = P$. Hence, \eqref{eqn:obuvw1}--\eqref{eqn:obuvw5} specializes to \eqref{eqn:snrbound1}--\eqref{eqn:snrbound5}. Moreover, \eqref{eqn:snrbound6} and \eqref{eqn:snrbound7} are precisely the positive semi-definiteness requirements in \eqref{eqn:psdxyu} and \eqref{eqn:psdxyv}, whereas \eqref{eqn:snrbound8} and \eqref{eqn:snrbound9} follow from Remark~\ref{rm:constraint_C}.

Lastly, the bounds \eqref{eqn:snrbound1}--\eqref{eqn:snrbound5} depend on
$\rho,\hat\rho$ only through $\rho^2,\hat\rho^2$, while for $\rho<0$
\[
    \bigl(P-|\rho|\sqrt{K_1K_2}\bigr)^2
    \leq\bigl(P-\rho\sqrt{K_1K_2}\bigr)^2
    \leq (P-K_1)(P+N_1-K_2),
\]
so that $(K_1,K_2,|\rho|)$ remains feasible and attains the same five values;
the same argument applies to $\hat\rho$.  We may therefore restrict attention
to $\rho,\hat\rho\in[0,1]$.

It suffices to show the upper bounds in Proposition~\ref{prop:obuvwgauss} and Theorem~\ref{ob:ayfergaussian} coincide.

\emph{Step 1: elimination of $\rho$ and $\hat\rho$.}

Each right-hand side in \eqref{eqn:snrbound1}--\eqref{eqn:snrbound5} is
non-increasing in $\rho^2$ and in $\hat\rho^2$, so it is optimal to choose
$\rho^2,\hat\rho^2$ as small as permitted:
\begin{subequations}
    \begin{align}
        \rho = &\max\bigg\{0,\frac{P-\sqrt{(P-K_1)(P+N_1-K_2)}}{\sqrt{K_1K_2}}\bigg\},\label{eqn:k1k2rho1}\\
        \hat \rho=&\max\bigg\{0, \frac{P-\sqrt{(P-\hat K_1)(P+N_2-\hat K_2)}}{\sqrt{\hat K_1\hat K_2}}\bigg\}.\label{eqn:k1k2rho2}
    \end{align}
\end{subequations}
When $\rho,\hat \rho>0$, \eqref{eqn:k1k2rho1} and \eqref{eqn:k1k2rho2} can be rewritten as
\begin{subequations}\label{eqn:sident}
    \begin{align}
        K_2\bigl(1-\rho^2\bigr) =& N_1
        -\frac{P}{K_1}\Bigl(\sqrt{P+N_1-K_2}-\sqrt{P-K_1}\Bigr)^2
        \ \leq\ N_1,\\
        \hat K_2\bigl(1-\hat\rho^2\bigr) =& N_2
        -\frac{P}{\hat K_1}\Bigl(\sqrt{P+N_2-\hat K_2}
        -\sqrt{P-\hat K_1}\Bigr)^2\ \leq\ N_2 .
    \end{align}
\end{subequations}

\emph{Step 2: trigonometric substitution.}

In view of \eqref{eqn:snrbound8}, \eqref{eqn:snrbound9}, and \eqref{eqn:sident}, define
\begin{subequations}\label{eqn:chart}
    \begin{align}
        \psi_1:=\arcsin\sqrt{\frac{K_2\bigl(1-\rho^2\bigr)}{N_1}}
        \ \in\ \Bigl[\arcsin\bigl(2^{-C_1}\bigr),\tfrac{\pi}{2}\Bigr],\\
        \psi_2:=\arcsin\sqrt{\frac{\hat K_2\bigl(1-\hat\rho^2\bigr)}{N_2}}
        \ \in\ \Bigl[\arcsin\bigl(2^{-C_2}\bigr),\tfrac{\pi}{2}\Bigr].
    \end{align}
\end{subequations}
After substitution, \eqref{eqn:snrbound1}--\eqref{eqn:snrbound9} then equal
\begin{subequations}
    \begin{align}
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_2}\Bigr)+C_1
               +\log\sin\psi_1,\label{eqn:psibound1}\\
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_1}\Bigr)
               +\tfrac{1}{2}\log\Bigl(1+\tfrac{K_1}{N_2}\Bigr)
               +\tfrac{1}{2}\log\frac{N_1\sin^{2}\psi_1}
               {P+N_1-\bigl(\sqrt{P-K_1}
                +\cos\psi_1\sqrt{\tfrac{N_1K_1}{P}}\bigr)^{2}},
               \label{eqn:psibound2}\\
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_1}\Bigr)+C_2
               +\log\sin\psi_2,\label{eqn:psibound3}\\
        R\leq &\tfrac{1}{2}\log\Bigl(1+\tfrac{P}{N_2}\Bigr)
               +\tfrac{1}{2}\log\Bigl(1+\tfrac{\hat K_1}{N_1}\Bigr)
               +\tfrac{1}{2}\log\frac{N_2\sin^{2}\psi_2}
               {P+N_2-\bigl(\sqrt{P-\hat K_1}
                +\cos\psi_2\sqrt{\tfrac{N_2\hat K_1}{P}}\bigr)^{2}},
               \label{eqn:psibound4}\\
        R\leq & C_1+C_2+\log\sin\psi_1+\log\sin\psi_2 ,\label{eqn:psibound5}
    \end{align}
\end{subequations}
    for some $\psi_1\in(\arcsin(2^{-C_1}),\frac{\pi}{2}]$, $\psi_2\in(\arcsin(2^{-C_2}),\frac{\pi}{2}]$, and $K_1\in[\frac{PN_1\cos^2\psi_1}{P+N_1\cos^2\psi_1},\,P]$, $\hat K_1\in[\frac{PN_2\cos^2\psi_2}{P+N_2\cos^2\psi_2},\,P]$.

Upon relating $(\psi_1,\psi_2)$ with $(\theta_1,\theta_2)$, the constraints \eqref{eqn:psibound1}, \eqref{eqn:psibound3}, and \eqref{eqn:psibound5} coincide with \eqref{eqn:ayfergauss1}, \eqref{eqn:ayfergauss3}, and \eqref{eqn:ayfergauss5}, respectively. It remains to show that \eqref{eqn:psibound2} and \eqref{eqn:psibound4} coincide with \eqref{eqn:ayfergauss2} and \eqref{eqn:ayfergauss4}.

\emph{Step 3: two explicit optimizations.}

A direct computation yields
\begin{subequations}
    \begin{align}
    &\max_{K_1\in\bigl[\frac{PN_1\cos^{2}\psi_1}{P+N_1\cos^{2}\psi_1},\,P\bigr]}
    \frac{1}{2}\log\Bigl(1+\frac{P}{N_1}\Bigr)
    +\frac{1}{2}\log\Bigl(1+\frac{K_1}{N_2}\Bigr)
    +\frac{1}{2}\log\frac{N_1\sin^{2}\psi_1}
      {P+N_1-\bigl(\sqrt{P-K_1}
       +\cos\psi_1\sqrt{\frac{N_1K_1}{P}}\bigr)^{2}}\nonumber\\
    =&\frac{1}{2}\log\left[\left(1+
      \frac{P(N_1+N_2)+N_1N_2\cos^{2}\psi_1
            +\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\psi_1\bigr]^{2}
                   -4P^{2}N_1N_2\sin^{2}\psi_1}}
           {2N_1N_2\sin^{2}\psi_1}\right)\sin^{2}\psi_1\right],
    \label{eqn:finalpsibound2}\\
    &\max_{\hat K_1\in\bigl[\frac{PN_2\cos^{2}\psi_2}{P+N_2\cos^{2}\psi_2},\,P\bigr]}
    \frac{1}{2}\log\Bigl(1+\frac{P}{N_2}\Bigr)
    +\frac{1}{2}\log\Bigl(1+\frac{\hat K_1}{N_1}\Bigr)
    +\frac{1}{2}\log\frac{N_2\sin^{2}\psi_2}
      {P+N_2-\bigl(\sqrt{P-\hat K_1}
       +\cos\psi_2\sqrt{\frac{N_2\hat K_1}{P}}\bigr)^{2}}\nonumber\\
    =&\frac{1}{2}\log\left[\left(1+
      \frac{P(N_1+N_2)+N_1N_2\cos^{2}\psi_2
            +\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\psi_2\bigr]^{2}
                   -4P^{2}N_1N_2\sin^{2}\psi_2}}
           {2N_1N_2\sin^{2}\psi_2}\right)\sin^{2}\psi_2\right],
    \label{eqn:finalpsibound4}
\end{align}
\end{subequations}
where the maximizers, whose feasibility proof is omitted here, are given by
\begin{align*}
    K_1^{\star}&=\frac{P^{2}\bigl[P(N_1-N_2)-N_1N_2\cos^{2}\psi_1+A\bigr]^{2}}
    {P\bigl[P(N_1-N_2)-N_1N_2\cos^{2}\psi_1+A\bigr]^{2}
     +N_1\cos^{2}\psi_1
      \bigl[2P^{2}+P(N_1+N_2)+N_1N_2\cos^{2}\psi_1-A\bigr]^{2}},\\
    A&:=\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\psi_1\bigr]^{2}
             -4P^{2}N_1N_2\sin^{2}\psi_1},\\
    \hat K_1^{\star}&=\frac{P^{2}\bigl[P(N_2-N_1)-N_1N_2\cos^{2}\psi_2
        +\hat A\bigr]^{2}}
    {P\bigl[P(N_2-N_1)-N_1N_2\cos^{2}\psi_2+\hat A\bigr]^{2}
     +N_2\cos^{2}\psi_2
      \bigl[2P^{2}+P(N_1+N_2)+N_1N_2\cos^{2}\psi_2-\hat A\bigr]^{2}},\\
    \hat A&:=\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\psi_2\bigr]^{2}
             -4P^{2}N_1N_2\sin^{2}\psi_2}.
\end{align*}

The minimization problems in \eqref{eqn:ayfergauss2} and
\eqref{eqn:ayfergauss4} admit explicit solutions as well:
\begin{subequations}
    \begin{align}
    &\frac{1}{2}\log\Bigl(1+\frac{P}{N_2}\Bigr)
    +\min_{\omega_1\in(\frac{\pi}{2}-\theta_1,\frac{\pi}{2}]}
     h_1(\omega_1;\theta_1)\nonumber\\
    =&\frac{1}{2}\log\left[\left(1+
      \frac{P(N_1+N_2)+N_1N_2\cos^{2}\theta_1
            +\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\theta_1\bigr]^{2}
                   -4P^{2}N_1N_2\sin^{2}\theta_1}}
           {2N_1N_2\sin^{2}\theta_1}\right)\sin^{2}\theta_1\right],
    \label{eqn:finalayferbound2}\\
    &\frac{1}{2}\log\Bigl(1+\frac{P}{N_1}\Bigr)
    +\min_{\omega_2\in(\frac{\pi}{2}-\theta_2,\frac{\pi}{2}]}
     h_2(\omega_2;\theta_2)\nonumber\\
    =&\frac{1}{2}\log\left[\left(1+
      \frac{P(N_1+N_2)+N_1N_2\cos^{2}\theta_2
            +\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\theta_2\bigr]^{2}
                   -4P^{2}N_1N_2\sin^{2}\theta_2}}
           {2N_1N_2\sin^{2}\theta_2}\right)\sin^{2}\theta_2\right],
    \label{eqn:finalayferbound4}
\end{align}
\end{subequations}
where the minimizers, whose feasibility proof is omitted here, are given by
\begin{align*}
    \cos\omega_1^{\star}
    =&\frac{2P\sqrt{N_1N_2}\,\sin^{2}\theta_1}
           {P(N_1+N_2)+N_1N_2\cos^{2}\theta_1
            +\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\theta_1\bigr]^{2}
                   -4P^{2}N_1N_2\sin^{2}\theta_1}},\\
    \cos\omega_2^{\star}
    =&\frac{2P\sqrt{N_1N_2}\,\sin^{2}\theta_2}
           {P(N_1+N_2)+N_1N_2\cos^{2}\theta_2
            +\sqrt{\bigl[P(N_1+N_2)+N_1N_2\cos^{2}\theta_2\bigr]^{2}
                   -4P^{2}N_1N_2\sin^{2}\theta_2}}.
\end{align*}
Since \eqref{eqn:finalayferbound2} and \eqref{eqn:finalayferbound4} are identical to \eqref{eqn:finalpsibound2} and \eqref{eqn:finalpsibound4} when relating $(\psi_1,\psi_2)$ with $(\theta_1,\theta_2)$, \eqref{eqn:psibound2} and \eqref{eqn:psibound4} coincide with \eqref{eqn:ayfergauss2} and \eqref{eqn:ayfergauss4}, which completes the proof.
